sub get_panel_user
{
	my $c = shift;
	my $adb = esmith::AccountsDB::UTF8->open();
	if (!$c->is_admin){
		return $c->session->{username};
	} else {
		if (my $thisUser = $c->param('account')) {
			#Check it is a valid user
			if ($adb->get_prop($thisUser, "FirstName")){
				return $thisUser
			} else {
				return $c->session->{username}
			}
		} else {
			return $c->session->{username}
		}
	}
}

